/**
 * The Gibeonites
 * --------------
 * The Gibeonites come in worn clothes and dry bread, pretending to be from afar, and a covenant is made. Stage: a camp at noon, dusty travellers with patched sandals and dry bread, a treaty sealed; a leader's oath, a lesson in haste.
 *
 * Palette 0x2a1a10 → 0x060402 · light: dawn · hero: bread
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./joshua-kit.js.
 */

import { THREE, createScene, tent, wheat, person } from './joshua-kit.js';

const BG = 0x2a1a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2978729154, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents */
    tent(W, group, -18.6, 0, -5.4, 1.33, 0xa8704a, W.r() * 6);
    tent(W, group, -26.4, 0, -14.7, 1.25, 0xa8704a, W.r() * 6);
    tent(W, group, 26.9, 0, -21.9, 1.34, 0xd8c8a0, W.r() * 6);

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x2e1d12, head: 0x352114 });

    /* hero: the bread */
    for (let i = 0; i < 3; i++) {
        W.add(group, W.G('dod', 0.5), W.mat(0xd8b878, { rough: 0.7 }), [0 - 1 + i, 0.35, 0 + (i % 2) * 0.8 - 0.4], { s: [1, 0.5, 0.8] });
    }
    W.disc([0, 3.5, -10], 3, 0x372215, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2a1a10, ry: 0.45, s: 1.02 });

    return W.finish();
}

export default { build };
